rule CobaltStrike_Beacon_Generic {
    meta:
        description = "Detects generic Cobalt Strike beacon patterns"
        author = "SOC_Team"
        confidence = "medium"
        false_positive_risk = "high"
        red_team_tested = true
    strings:
        $x64_jmp = { FF /2 0F 1F 44 00 00 }
        $cfg_junk = { 83 C0 ?? 48 8D } 
        $decrypt = "Decrypt" wide ascii
    condition:
        $x64_jmp and $cfg_junk and $decrypt
}
